/* WARNING: Script requires that SQLITE_DBCONFIG_DEFENSIVE be disabled */
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE zimrx_static_drug_dosing (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            brand_name TEXT,
            brand_id TEXT,
            generic_id TEXT,
            generic_name TEXT,
            strength TEXT,
            form TEXT,
            dose TEXT,
            instruction TEXT,
            duration TEXT,
            created_at TEXT,
            updated_at TEXT
        );
CREATE TABLE zimrx_static_zscore (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            type TEXT,
            sex TEXT,
            age_month INTEGER,
            measurement TEXT,
            l REAL,
            m REAL,
            s REAL,
            source TEXT
        );
CREATE TABLE zimrx_static_chart_images (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            chart_type TEXT,
            title TEXT,
            image_path TEXT,
            description TEXT,
            sort_order INTEGER NOT NULL DEFAULT 0
        );
CREATE TABLE zimrx_static_db_version (
            id INTEGER PRIMARY KEY CHECK (id = 1),
            version TEXT NOT NULL,
            migrated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            notes TEXT
        );
CREATE TABLE IF NOT EXISTS zimrx_address_hierarchy (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    country TEXT NOT NULL,
    parent_id INTEGER NULL,
    level INTEGER NOT NULL,
    place_type TEXT NOT NULL,
    name_en TEXT NOT NULL,
    name_loc TEXT NULL,
    postcode TEXT NULL,
    FOREIGN KEY(parent_id) REFERENCES zimrx_address_hierarchy(id)
);
CREATE INDEX IF NOT EXISTS idx_address_country_search ON zimrx_address_hierarchy(country, name_en COLLATE NOCASE, name_loc);
CREATE INDEX IF NOT EXISTS idx_address_parent ON zimrx_address_hierarchy(parent_id);
CREATE INDEX IF NOT EXISTS idx_address_level_type ON zimrx_address_hierarchy(country, level, place_type);
CREATE TABLE IF NOT EXISTS "zimrx_static_instructions" (
        id INTEGER PRIMARY KEY,
        instruction_en TEXT,
        instruction_bn TEXT,
        search_alias TEXT,
        sort_order INTEGER,
        default_dosage_form TEXT,
        default_instruction_in_another_row INTEGER
    );
CREATE TABLE zimrx_static_doses (id INTEGER PRIMARY KEY, dosage_bn TEXT, dosage_en TEXT, search_alias TEXT, sort_order INTEGER, default_dosage_form TEXT NOT NULL DEFAULT '[]');
CREATE TABLE zimrx_static_durations (id INTEGER PRIMARY KEY, duration_bn TEXT, duration_en TEXT, search_alias TEXT, sort_order INTEGER, default_dosage_form TEXT NOT NULL DEFAULT '[]');
CREATE TABLE zimrx_static_advices (id INTEGER PRIMARY KEY, category_id INTEGER NOT NULL, category_sort_order INTEGER NOT NULL DEFAULT 0, category_bn TEXT NOT NULL DEFAULT '', category_en TEXT NOT NULL DEFAULT '', category_search_alias TEXT NOT NULL DEFAULT '', advice_sort_order INTEGER NOT NULL DEFAULT 0, advice_bn TEXT NOT NULL DEFAULT '', advice_en TEXT NOT NULL DEFAULT '', sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE zimrx_static_medical_history (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    category VARCHAR(100) NOT NULL,
    condition_key VARCHAR(100) NOT NULL UNIQUE,
    display_label VARCHAR(150) NOT NULL,
    full_name VARCHAR(255) NOT NULL,
    field_type VARCHAR(50) NOT NULL DEFAULT 'none', -- 'none', 'textbox', 'dropdown', 'dropdown_text'
    dropdown_options TEXT DEFAULT '',
    placeholder TEXT DEFAULT '',
    is_default_active INTEGER DEFAULT 0, -- 1 = active in default OPD grid, 0 = customizable in settings
    sort_order INTEGER DEFAULT 10
);
CREATE TABLE zimrx_static_physical_examination (id INTEGER PRIMARY KEY AUTOINCREMENT, system VARCHAR(50) NOT NULL, category VARCHAR(100) NOT NULL, item_code VARCHAR(100) NOT NULL UNIQUE, display_name VARCHAR(100) NOT NULL, full_name VARCHAR(255) NOT NULL, input_type VARCHAR(50) NOT NULL, delimiter VARCHAR(10) DEFAULT '', default_unit VARCHAR(30) DEFAULT '', normal_value TEXT DEFAULT '', dropdown_options TEXT DEFAULT '', finding_wordlists TEXT DEFAULT '', is_default_active INTEGER DEFAULT 0, sort_order INTEGER DEFAULT 10);
CREATE TABLE zimrx_static_physical_examination_templates (id INTEGER PRIMARY KEY AUTOINCREMENT, template_key VARCHAR(100) NOT NULL UNIQUE, template_name VARCHAR(150) NOT NULL, specialty VARCHAR(100) NOT NULL, description TEXT DEFAULT '', items_json TEXT NOT NULL, is_system_default INTEGER DEFAULT 1, sort_order INTEGER DEFAULT 10);
CREATE TABLE zimrx_static_physical_examination_phrases (id INTEGER PRIMARY KEY AUTOINCREMENT, category VARCHAR(100) NOT NULL, phrase_title VARCHAR(150) NOT NULL, phrase_text TEXT NOT NULL, sort_order INTEGER DEFAULT 10);
CREATE TABLE zimrx_static_dx (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    dx_short TEXT NOT NULL,
    dx_full TEXT NOT NULL,
    acronym TEXT,
    search_aliases TEXT,
    specialty TEXT NOT NULL DEFAULT 'Medicine',
    system_category TEXT,
    priority_tier INTEGER NOT NULL DEFAULT 2
);
CREATE TABLE IF NOT EXISTS 'fts_zimrx_static_dx_data'(id INTEGER PRIMARY KEY, block BLOB);
CREATE TABLE IF NOT EXISTS 'fts_zimrx_static_dx_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS 'fts_zimrx_static_dx_docsize'(id INTEGER PRIMARY KEY, sz BLOB);
CREATE TABLE IF NOT EXISTS 'fts_zimrx_static_dx_config'(k PRIMARY KEY, v) WITHOUT ROWID;
ANALYZE sqlite_schema;
CREATE TABLE zimrx_static_pc (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    term TEXT NOT NULL,
    category TEXT NOT NULL DEFAULT 'finding'
);
CREATE TABLE IF NOT EXISTS 'fts_zimrx_static_pc_data'(id INTEGER PRIMARY KEY, block BLOB);
CREATE TABLE IF NOT EXISTS 'fts_zimrx_static_pc_idx'(segid, term, pgno, PRIMARY KEY(segid, term)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS 'fts_zimrx_static_pc_docsize'(id INTEGER PRIMARY KEY, sz BLOB);
CREATE TABLE IF NOT EXISTS 'fts_zimrx_static_pc_config'(k PRIMARY KEY, v) WITHOUT ROWID;
CREATE TABLE zimrx_static_investigations (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            category TEXT,
            price INTEGER DEFAULT 0,
            institute TEXT NOT NULL
        );
PRAGMA writable_schema=ON;
    dx_short,
    dx_full,
    acronym,
    search_aliases,
    content=''zimrx_static_dx'',
    content_rowid=''id'',
    tokenize=''unicode61''
)');
    term,
    category UNINDEXED,
    content=''zimrx_static_pc'',
    content_rowid=''id'',
    tokenize=''unicode61''
)');
CREATE TABLE zimrx_static_investigations_param (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    short_name TEXT NOT NULL,
    full_name TEXT NOT NULL,
    default_unit TEXT,
    all_units TEXT
);
CREATE TABLE zimrx_static_patches (
    patch_id TEXT PRIMARY KEY,
    patch_name TEXT,
    version TEXT,
    applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    checksum TEXT,
    notes TEXT
);
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_static_doses_sort ON zimrx_static_doses(sort_order, id);
CREATE INDEX idx_static_durations_sort ON zimrx_static_durations(sort_order, id);
CREATE INDEX idx_static_advices_category_en ON zimrx_static_advices(category_en);
CREATE INDEX idx_static_advices_category_id ON zimrx_static_advices(category_id);
CREATE INDEX idx_med_history_category ON zimrx_static_medical_history(category);
CREATE INDEX idx_med_history_key ON zimrx_static_medical_history(condition_key);
CREATE INDEX idx_med_history_active ON zimrx_static_medical_history(is_default_active);
CREATE INDEX idx_med_history_sort ON zimrx_static_medical_history(sort_order);
CREATE INDEX idx_static_pe_system ON zimrx_static_physical_examination (system);
CREATE INDEX idx_static_pe_category ON zimrx_static_physical_examination (category);
CREATE INDEX idx_static_pe_active ON zimrx_static_physical_examination (is_default_active);
CREATE INDEX idx_static_pe_input ON zimrx_static_physical_examination (input_type);
CREATE INDEX idx_static_pe_code ON zimrx_static_physical_examination (item_code);
CREATE INDEX idx_static_dx_short ON zimrx_static_dx(dx_short COLLATE NOCASE);
CREATE INDEX idx_static_dx_acronym ON zimrx_static_dx(acronym COLLATE NOCASE);
CREATE INDEX idx_static_dx_specialty ON zimrx_static_dx(specialty);
CREATE INDEX idx_static_dx_priority ON zimrx_static_dx(priority_tier);
CREATE INDEX idx_static_pc_term ON zimrx_static_pc(term COLLATE NOCASE);
CREATE INDEX idx_static_pc_cat ON zimrx_static_pc(category);
CREATE INDEX idx_static_ix_name ON zimrx_static_investigations(name COLLATE NOCASE);
CREATE INDEX idx_static_ix_category ON zimrx_static_investigations(category);
CREATE INDEX idx_static_ix_institute ON zimrx_static_investigations(institute);
CREATE INDEX idx_static_ix_param_short ON zimrx_static_investigations_param(short_name COLLATE NOCASE);
CREATE INDEX idx_static_ix_param_full ON zimrx_static_investigations_param(full_name COLLATE NOCASE);
PRAGMA writable_schema=OFF;
COMMIT;
