INSERT INTO zimrx_static_physical_examination VALUES(77,'ENT','Oral Cavity & Throat','oral_cavity','Oral Cavity','Oral Mucosa, Tongue & Gums','dropdown+textbox','','','Oral mucosa pink and moist, tongue clean, gums healthy','Oral mucosa pink & moist, tongue clean|Oral candidiasis / Thrush|Aphthous ulcer|Leukoplakia|Dental caries present|Gingivitis / Bleeding gums','Oral mucosa, Pink, Moist, Dry, Stomatitis, Gingivitis, Bleeding gums, Gum hypertrophy (Phenytoin, leukaemia), Scurvy, Pyorrhoea, Dental caries, Poor oral hygiene, Tongue clean, Coated tongue, Geographic tongue, Strawberry tongue (Scarlet fever, Kawasaki disease), Magenta tongue (Riboflavin deficiency), Glossitis / Smooth red beefy tongue (B12 / Folate / Iron deficiency), Macroglossia (Down syndrome, hypothyroidism, amyloidosis), Leukoplakia (White non-scrapable patch), Erythroplakia, Oral candidiasis / Thrush (White curd-like scrapable plaques over erythematous base), Aphthous ulcer (Painful shallow ulcer with yellow-grey base and erythematous halo), Oral submucous fibrosis (Blanched mucosa, fibrous bands, trismus)',0,30);
INSERT INTO zimrx_static_physical_examination VALUES(78,'ENT','Oral Cavity & Throat','throat_tonsils','Throat/Tonsils','Pharynx, Tonsils & Uvula','dropdown+textbox','','','Pharynx clear, tonsils normal size, no exudates','Pharynx clear, tonsils normal|Tonsils enlarged Grade I-II|Tonsils enlarged Grade III-IV (Kissing)|Congested tonsils with white exudates|Posterior pharyngeal wall congested','Posterior pharyngeal wall, Clear, Congested, Granular pharynx (Cobblestoning in chronic pharyngitis/postnasal drip), Tonsils within pillars, Tonsillar enlargement Grade 1 (<25% of airway), Grade 2 (25-50%), Grade 3 (50-75%), Grade 4 (>75% / Kissing tonsils), Acute follicular tonsillitis (Erythematous tonsils with white/yellow follicular exudates), Quinsy / Peritonsillar abscess (Unilateral tonsillar bulge, uvula pushed to opposite side, trismus, hot potato voice), Diphtheritic membrane (Grey-white adherent pseudomembrane over tonsils/pharynx that bleeds on peeling), Uvula midline, Uvular oedema, Bifid uvula',0,40);
INSERT INTO zimrx_static_physical_examination VALUES(79,'Eye','Vision & External','visual_acuity','Visual Acuity','Visual Acuity (Snellen Chart R/L)','double_textbox','/','','6/6 / 6/6','','Visual acuity, Snellen chart, 6/6, 6/9, 6/12, 6/18, 6/24, 6/36, 6/60, Right eye (OD), Left eye (OS), Both eyes (OU), Pinhole improvement, Counting fingers at ... meters, Hand movements (HM), Perception of light (PL), No perception of light (NPL), Refractive error, Myopia, Hypermetropia, Presbyopia, Astigmatism',0,10);
INSERT INTO zimrx_static_physical_examination VALUES(80,'Eye','Anterior Segment','conjunctiva_sclera','Conjunctiva','Conjunctiva, Sclera & Cornea','dropdown+textbox','','','Conjunctiva clear, white sclera, cornea clear and transparent','Conjunctiva clear, white sclera|Conjunctival injection / Hyperaemia|Subconjunctival haemorrhage|Pterygium present|Corneal opacity / Ulcer','Conjunctiva clear, Palpebral conjunctiva, Bulbar conjunctiva, Conjunctival hyperaemia, Conjunctival injection, Ciliary flush (Deep violaceous perilimbal injection in iritis/keratitis), Purulent discharge, Mucoid discharge, Watery discharge, Subconjunctival haemorrhage (Bright red circumscribed flat patch), Chemosis (Conjunctival oedema), Pterygium (Triangular fibrovascular growth onto cornea), Pinguecula, Sclera white, Scleral icterus, Blue sclera (Osteogenesis imperfecta), Episcleritis, Scleritis, Cornea transparent, Corneal opacity, Corneal ulcer, Keratitis, Dendritic ulcer (Herpes simplex), Arcus senilis (Corneal arcus), Kayser-Fleischer ring (KF ring in Wilson disease, brown copper ring at limbus), Anterior chamber deep and quiet, Hypopyon (Pus in AC), Hyphaema (Blood in AC)',0,20);
INSERT INTO zimrx_static_physical_examination VALUES(81,'Eye','Posterior Segment','fundoscopy','Fundoscopy','Ophthalmoscopy & Retinal Fundus','dropdown+textbox','','','Normal disc margins, CDR 0.3, vessels normal, no haemorrhages','Normal disc margins, CDR 0.3|Papilloedema (Disc swelling)|Hypertensive retinopathy Grade I-II|Diabetic retinopathy (NPDR)|Pale optic disc (Atrophy)','Optic disc, Cup-to-disc ratio (CDR 0.3), Sharp disc margins, Blurring of disc margins, Papilloedema (Elevated hyperaemic disc, blurred margins, loss of venous pulsation, flame haemorrhages, raised ICP), Optic disc pallor / Optic atrophy, Cupping of optic disc (Glaucoma, CDR >0.6, asymmetry), Arteriovenous (AV) ratio (2:3), Copper wiring of arterioles, Silver wiring, AV nipping / AV nicking (Gunn sign, Salus sign), Flame-shaped retinal haemorrhages, Dot and blot haemorrhages, Hard exudates (Lipid deposits), Cotton-wool spots / Soft exudates (Micro-infarcts), Microaneurysms, Neovascularization at disc (NVD), Neovascularization elsewhere (NVE), Non-proliferative diabetic retinopathy (NPDR), Proliferative diabetic retinopathy (PDR), Diabetic macular oedema, Cherry-red spot at macula (Central retinal artery occlusion), Blood and thunder appearance (Central retinal vein occlusion)',0,30);
INSERT INTO zimrx_static_physical_examination VALUES(82,'Skin','Lesions & Rashes','skin_lesions','Skin Lesions','Dermatological Primary & Secondary Lesions','dropdown+textbox','','','Skin clear, warm and intact, no primary or secondary lesions','Skin clear, no active lesions|Maculopapular rash|Vesicular lesions on red base|Psoriatic plaques with silver scale|Urticarial wheals|Eczematous patches','Macule (<1 cm flat), Patch (>1 cm flat), Papule (<1 cm raised), Plaque (>1 cm raised, flat-topped), Nodule (>1 cm solid, deep), Wheal (Transient oedematous papule/plaque), Vesicle (<1 cm fluid-filled), Bulla (>1 cm fluid-filled), Pustule (Pus-filled), Cyst, Scale (Flakes of stratum corneum), Crust (Dried exudate/blood), Lichenification (Thickened skin with accentuated skin markings), Excoriation (Scratch marks), Fissure (Linear cleavage of skin), Erosion (Loss of epidermis), Ulcer (Loss of epidermis and dermis), Scar, Atrophy, Telangiectasia, Annular lesions (Ring-shaped), Target / Iris lesions (Erythema multiforme), Grouped dermatomal vesicles (Herpes zoster), Silvery scales with Auspitz sign positive (Psoriasis), Nikolsky sign positive (Pemphigus vulgaris), Wickham striae (Lichen planus), Koebner phenomenon positive, Burrows in web spaces (Scabies)',0,10);
INSERT INTO zimrx_static_physical_examination VALUES(83,'Skin','Ulcers & Wounds','skin_ulcer','Ulcer/Wound','Ulcer, Wound & Surgical Site Assessment','dropdown+textbox','','cm','No ulcers, skin intact','No active ulcer or wound|Clean granulating ulcer|Diabetic foot ulcer (Superficial)|Diabetic foot ulcer (Deep to tendon)|Slough & purulent discharge|Healing surgical wound','cm, Location, Size (length x width x depth cm), Ulcer base, Healthy pink granulation tissue, Yellow slough present, Black necrotic eschar, Purulent discharge, Serous discharge, Foul odor, Edge: Sloping edge (Healing venous ulcer), Punched-out edge (Arterial ulcer / Syphilitic gumma), Undermined edge (Tuberculous ulcer), Rolled / Beaded pearly edge (Basal cell carcinoma), Everted / Raised edge (Squamous cell carcinoma), Surrounding skin: Cellulitis, Erythema, Induration, Warmth, Hyperpigmentation, Lipodermatosclerosis, Varicose eczema, Peripheral pulses, Sensation around ulcer, Diabetic foot ulcer (Wagner Grade 0-5), Pressure ulcer / Bedsore (Stage I-IV)',0,20);
INSERT INTO zimrx_static_physical_examination VALUES(84,'Pediatric','Growth & Vitals','fontanelle','Fontanelle','Anterior Fontanelle Tension & Closure','dropdown+textbox','','','Level, soft and normotensive','Level, soft and normotensive|Closed (appropriate for age)|Sunken (Dehydration)|Bulging / Tense (Raised ICP/Meningitis)|Widely patent','Anterior fontanelle, Level, Soft, Normotensive, Pulsatile, Sunken fontanelle (Dehydration, malnutrition), Bulging fontanelle (Raised intracranial pressure, meningitis, hydrocephalus, encephalitis), Tense, Delayed closure of fontanelle (Rickets, hydrocephalus, hypothyroidism, Down syndrome), Premature closure (Craniosynostosis), Posterior fontanelle (Closed by 6-8 weeks), Third fontanelle',0,10);
INSERT INTO zimrx_static_physical_examination VALUES(85,'Pediatric','Growth & Vitals','ofc','OFC','Occipitofrontal Circumference (Head Circ)','textbox','','cm','','','cm, inches, Occipitofrontal circumference (OFC), Head circumference, Centile, 50th centile, Microcephaly (< -2 SD or < 3rd centile), Macrocephaly (> +2 SD or > 97th centile), Suture separation, Hydrocephalus, Sun-setting eye sign, Macewen sign / Cracked-pot sound positive',0,20);
INSERT INTO zimrx_static_physical_examination VALUES(86,'Pediatric','Growth & Vitals','muac','MUAC','Mid-Upper Arm Circumference','dropdown+textbox','','cm','','Normal (> 12.5 cm - Green)|Moderate Acute Malnutrition (11.5 - 12.5 cm - Yellow)|Severe Acute Malnutrition (< 11.5 cm - Red)','cm, mm, Mid-upper arm circumference (MUAC), Green zone (>12.5 cm, Well-nourished), Yellow zone (11.5-12.5 cm, Moderate Acute Malnutrition - MAM), Red zone (<11.5 cm, Severe Acute Malnutrition - SAM), Shakir strip, Nutritional assessment 6-59 months, Bipedal nutritional oedema',0,30);
INSERT INTO zimrx_static_physical_examination VALUES(87,'Pediatric','Development','primitive_reflexes','Reflexes (Ped)','Neonatal & Primitive Reflexes','dropdown+textbox','','','Moro, grasp, rooting and sucking reflexes present & symmetrical','Moro, grasp, rooting & sucking present|Moro reflex absent / asymmetric|Poor sucking reflex|Grasp reflex sluggish','Moro reflex present and symmetrical, Asymmetric Moro reflex (Brachial plexus injury / Erb palsy, fractured clavicle, hemiplegia), Absent Moro (Severe brain injury, hypotonia), Rooting reflex, Sucking reflex, Palmar grasp reflex, Plantar grasp reflex, Asymmetrical tonic neck reflex (ATNR / Fencing posture), Stepping reflex, Galant reflex, Persistence of primitive reflexes (Cerebral palsy)',0,40);
INSERT INTO zimrx_static_physical_examination VALUES(88,'Obs/Gynae','Obstetric Palpation','sfh','Fundal Height','Symphysio-Fundal Height (SFH)','textbox','','cm','','','cm, weeks, Symphysio-fundal height (SFH), Measured from superior border of pubic symphysis to fundus, Corresponds to gestational age in weeks (20-36 weeks: SFH in cm = gestational age in weeks ┬▒ 2 cm), Fundus at pubic symphysis (12 weeks), Fundus midway to umbilicus (16 weeks), Fundus at umbilicus (20-24 weeks), Fundus at xiphisternum (36 weeks), Small for gestational age (Fetal growth restriction - FGR, oligohydramnios, transverse lie, wrong dates), Large for gestational age (Macrosomia, polyhydramnios, multiple pregnancy, fibroid, wrong dates)',0,10);
INSERT INTO zimrx_static_physical_examination VALUES(89,'Obs/Gynae','Obstetric Palpation','fhr','FHR','Fetal Heart Rate & Sounds','dropdown+textbox','','bpm','140','130 - 150 bpm, regular|Fetal tachycardia (> 160 bpm)|Fetal bradycardia (< 110 bpm)|Absent fetal heart sounds','bpm, Fetal heart rate (FHR), Normal range 110-160 bpm, Regular, Audible by Pinard stethoscope, Audible by Doppler ultrasound, Fetal tachycardia (>160 bpm, maternal fever, chorioamnionitis, fetal hypoxia), Fetal bradycardia (<110 bpm, acute fetal distress, cord compression), Baseline variability, Accelerations present, Decelerations (Early, Variable, Late decelerations on CTG)',0,20);
