INSERT INTO zimrx_static_physical_examination VALUES(91,'Obs/Gynae','Obstetric Palpation','fetal_movements','Fetal Movements','Fetal Movements (FM / Kicks)','dropdown+textbox','','','Active fetal movements felt by mother (> 10 kicks/12h)','Active fetal movements felt (> 10 kicks/12h)|Good fetal movements reported|Reduced fetal movements reported','Active fetal movements felt, Good kick count, Fetal movements perceived, > 10 movements in 12 hours (Cardiff count-to-ten method), Reduced fetal movements (RFM), Sluggish fetal movements, Absent fetal movements (Requires immediate CTG / Obstetric ultrasound / BPP)',0,40);
