INSERT INTO zimrx_static_physical_examination_phrases VALUES(1,'General','All Normal GPE','General physical examination reveals patient is comfortable at rest, well-oriented, non-toxic. No pallor, icterus, cyanosis, clubbing or pedal oedema.',10);
INSERT INTO zimrx_static_physical_examination_phrases VALUES(2,'CVS','CVS Normal','CVS: Apex beat in left 5th ICS MCL. S1 and S2 audible, no murmurs or added sounds.',20);
INSERT INTO zimrx_static_physical_examination_phrases VALUES(3,'Respiratory','Chest Clear','Resp: Chest movements bilaterally symmetrical. Breath sounds are vesicular with normal expiration. No rhonchi or crepitations heard.',30);
INSERT INTO zimrx_static_physical_examination_phrases VALUES(4,'Abdomen','Abdomen Normal','Abd: Soft, non-tender throughout. No palpable organomegaly or masses. Bowel sounds are normal and active.',40);
INSERT INTO zimrx_static_physical_examination_phrases VALUES(5,'CNS','CNS Grossly Intact','CNS: Conscious, alert, GCS 15/15. Cranial nerves intact. Motor power 5/5 in all four limbs. Reflexes normal (++), plantars flexor bilaterally.',50);
INSERT INTO zimrx_static_physical_examination_phrases VALUES(6,'ENT','ENT Normal','ENT: Both tympanic membranes intact and pearly. Nasal septum midline. Tonsils within pillars, non-congested. No cervical lymphadenopathy.',60);
INSERT INTO zimrx_static_physical_examination_phrases VALUES(7,'Infection','Acute Pharyngitis','Throat: Congested posterior pharyngeal wall with enlarged, hyperaemic tonsils and white follicular exudates. Tender jugulodigastric lymph nodes palpable.',70);
INSERT INTO zimrx_static_physical_examination_phrases VALUES(8,'Respiratory','Acute Bronchospasm','Chest: Bilateral prolonged expiratory wheeze and diffuse polyphonic rhonchi heard throughout both lung fields. Tachypneic with mild intercostal retraction.',80);
INSERT INTO zimrx_static_physical_examination_phrases VALUES(9,'Cardiology','Congestive Failure','Raised JVP (> 4 cm above sternal angle). Bilateral basal fine inspiratory crepitations with bipedal pitting oedema up to mid-calf. S3 gallop audible at apex.',90);
